import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2024-02-01');
  assert.equal(Array.isArray(result), true);
  assert.equal(result.length, 0);
});

test('overdueInvoices excludes invoices with dueDate on or after asOf', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  // dueDate: 2024-01-29

  const result = overdueInvoices([issued], '2024-01-29');
  assert.equal(result.length, 0);

  const result2 = overdueInvoices([issued], '2024-01-30');
  assert.equal(result2.length, 1);
});

test('overdueInvoices includes invoice with dueDate strictly before asOf', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  // dueDate: 2024-01-29

  const result = overdueInvoices([issued], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2024-0001');
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  // dueDate: 2024-01-29

  const result = overdueInvoices([issued], '2024-02-05');
  assert.equal(result.length, 1);
  // 2024-01-29 to 2024-02-05 = 7 days
  assert.equal(result[0].daysOverdue, 7);
});

test('overdueInvoices includes issued invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;

  const result = overdueInvoices([issued], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2024-0001');
});

test('overdueInvoices includes partially_paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  const partial = recordPayment(issued, { amount: 10000, date: '2024-01-20' }).value;

  const result = overdueInvoices([partial], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2024-0001');
});

test('overdueInvoices excludes draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'

