import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { lineTotal, lineDiscount, lineVAT } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Get a list of overdue invoices.
 * @param {Array<{ number?: string, customerId: string, status: string, dueDate?: string, lines: Array, payments?: Array }>} invoices
 * @param {string} asOf date string in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter((inv) => inv.dueDate && inv.number)
    .filter((inv) => inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv)
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Get a VAT summary across invoices.
 * @param {Array<{ status: string, lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  // Map of VAT rate to { base, vat }
  const vatMap = {};

  // Process invoices with status 'issued', 'partially_paid', or 'paid'
  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
    .forEach((inv) => {
      inv.lines.forEach((line) => {
        const rate = line.vatRate;
        const base = lineTotal(line) - lineDiscount(line);
        const vat = lineVAT(line);

        if (!vatMap[rate]) {
          vatMap[rate] = { base: 0, vat: 0 };
        }

        vatMap[rate].base += base;
        vatMap[rate].vat += vat;
      });
    });

  // Convert to array and sort by rate descending
  return Object.entries(vatMap)
    .map(([rate, { base, vat }]) => ({
      rate: parseInt(rate, 10),
      base,
      vat
    }))
    .sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate the late fee for an invoice.
 * Late fee is 0.04% of the amount still due for every day the invoice is overdue.
 * @param {{ dueDate?: string, lines: Array, status?: string, payments?: Array }} invoice
 * @param {string} asOf date string in YYYY-MM-DD format
 * @returns {number} late fee in cents
 */
export function lateFee(invoice, asOf) {
  // Must have a due date
  if (!invoice.dueDate) {
    return 0;
  }

  // Calculate days overdue
  const daysOverdue = daysBetween(invoice.dueDate, asOf);

  // No fee if not overdue
  if (daysOverdue <= 0) {
    return 0;
  }

  // Get amount still due
  const due = balanceDue(invoice);

  // Calculate late fee: 0.04% per day
  const fee = due * 0.0004 * daysOverdue;

  return roundCents(fee);
}

